import itertools, sys

def is_nae_sat(num_vars, clauses):
    for assign in itertools.product([False, True], repeat=num_vars):
        ok=True
        for clause in clauses:
            vals=[assign[abs(lit)-1] ^ (lit<0) for lit in clause]
            if all(vals) or not any(vals):
                ok=False; break
        if ok:
            return True
    return False

# search for unsat instance with up to 4 vars and up to 3 clauses
for m in range(1,5):
    vars=list(range(1,m+1))
    lits=[v for v in vars]+[-v for v in vars]
    # generate clauses of 3 distinct vars
    all_clauses=[]
    for combo in itertools.combinations(vars,3):
        for signs in itertools.product([1,-1], repeat=3):
            clause=[s*abs(v) for s,v in zip(signs, combo)]
            all_clauses.append(clause)
    # try sets of 1 clause
    for c in all_clauses:
        if not is_nae_sat(m,[c]):
            print('found unsat single clause',m,c)
            sys.exit()
    # try 2 clauses
    for c1,c2 in itertools.combinations(all_clauses,2):
        if not is_nae_sat(m,[c1,c2]):
            print('unsat 2 clauses',m,c1,c2)
            sys.exit()
print('none found')
