import itertools, sys

def nae_ok(assign, clause):
    vals=[assign[abs(l)-1] ^ (l<0) for l in clause]
    return not (all(vals) or not any(vals))

def find_gadget(max_aux=2, max_clauses=3):
    # variables: 1=x,2=y,3=z, then aux 4..(3+max_aux)
    base_vars=[1,2,3]
    for aux_count in range(1, max_aux+1):
        total_vars=3+aux_count
        aux_vars=list(range(4,4+aux_count))
        all_vars=base_vars+aux_vars
        # generate all possible clauses of size 3 with distinct vars
        all_clauses=[]
        for combo in itertools.combinations(all_vars,3):
            for signs in itertools.product([1,-1], repeat=3):
                clause=[s*abs(v) for s,v in zip(signs, combo)]
                all_clauses.append(clause)
        # try subsets up to max_clauses
        for r in range(1, max_clauses+1):
            for subset in itertools.combinations(all_clauses, r):
                # condition: for any assignment to base vars, there exists assignment to aux vars making all clauses satisfied iff OR(base) true.
                good=True
                for base_assign in itertools.product([False,True], repeat=3):
                    # check existence of aux assignment satisfying all clauses
                    exists=False
                    for aux_assign in itertools.product([False,True], repeat=aux_count):
                        full_assign = list(base_assign)+list(aux_assign)
