import itertools, sys

def nae_ok(assign, clause):
    vals=[assign[abs(l)-1] ^ (l<0) for l in clause]
    return not (all(vals) or not any(vals))

def find_gadget(target_false=True, max_aux=2, max_clauses=5):
    for aux in range(1, max_aux+1):
        total = 1+aux
        vars = list(range(1,total+1))
        # generate all possible clauses
        all_clauses=[]
        for combo in itertools.combinations(vars,3):
            for signs in itertools.product([1,-1], repeat=3):
                clause=[s*abs(v) for s,v in zip(signs, combo)]
                all_clauses.append(clause)
        for r in range(1, max_clauses+1):
            for subset in itertools.combinations(all_clauses, r):
                sat_assigns=[]
                for assign in itertools.product([False,True], repeat=total):
                    if all(nae_ok(assign, cl) for cl in subset):
                        sat_assigns.append(assign)
                if not sat_assigns:
                    continue
                # check that all satisfying assignments have var1 == target_false
                if all(assign[0]==target_false for assign in sat_assigns):
                    print('Found gadget forcing var1', target_false, 'aux', aux, 'clauses', r)
                    print(subset)
                    return
    print('No gadget found')

